/// <summary>
/// Retrieves the default data for the passed sets from the header and line tables.
/// </summary>
/// <param name="_tableRefId">
/// The <c>TradeLineRefId</c> value that is used to filter the header and line tables.
/// </param>
/// <returns>
///  A container that has the following:
///  <list type="number">
///   <item>
///    <description>
///    The <c>VendInvoiceAccount</c> value that is used to select the open purchase orders.
///    </description>
///   </item>
///   <item>
///    <description>
///    The <c>CurrencyCode</c> value that is used to select the open purchase orders.
///    </description>
///   </item>
///   <item>
///    <description>
///    A packed set container of header <c>PurchIds</c>.
///    </description>
///   </item>
///   <item>
///    <description>
///    A packed set container of line <c>RecIds</c>.
///    </description>
///   </item>
///  </list>
/// </returns>
static container metGetPurchSetsData(TradeLineRefId _tableRefId)
{
    VendInvoiceAccount invcAccount;
    CurrencyCode currencyCode;

    VendInvoiceInfoTable vendInvoiceInfoTable;
    VendInvoiceInfoLine vendInvoiceInfoLine;
    PurchLine purchLine;


    Set purchPOSet;
    container purchPOCont;

    Set purchLineSet;
    container purchLineCont;

    if (_tableRefId != '')
    {
        purchPOSet = new Set(typeName2Type(extendedTypeStr(PurchId)));
        purchLineSet = new Set(typeName2Type(extendedTypeStr(RecId)));

        select firstonly InvoiceAccount, CurrencyCode from vendInvoiceInfoTable
            where vendInvoiceInfoTable.TableRefId == _tableRefId &&
                  vendInvoiceInfoTable.ParmId != '';

        if (vendInvoiceInfoTable.RecId)
        {
            invcAccount = vendInvoiceInfoTable.InvoiceAccount;
            currencyCode = vendInvoiceInfoTable.CurrencyCode;
        }

        while select PurchLineRecId, OrigPurchId from vendInvoiceInfoLine
           where vendInvoiceInfoLine.TableRefId == _tableRefId &&
                 vendInvoiceInfoLine.ParmId != '' &&
                 vendInvoiceInfoLine.PurchLineRecId != 0
        {
            purchPOSet.add(vendInvoiceInfoLine.OrigPurchId);
            purchLineSet.add(vendInvoiceInfoLine.PurchLineRecId);
        }


        SetEnumerator setEnumerator = purchPOSet.getEnumerator();
        while (setEnumerator.moveNext())
        {
            PurchId purchaseOrderId = setEnumerator.current();

            while select PurchId, RecId from purchLine
                where purchLine.PurchId == purchaseOrderId
                    && purchLine.PurchStatus == PurchStatus::Received
                    && purchLine.Blocked == NoYes::No
            notexists join vendInvoiceInfoLine
                where vendInvoiceInfoLine.PurchLineRecId == purchLine.RecId
                && vendInvoiceInfoLine.TableRefId == _tableRefId
                && vendInvoiceInfoLine.ParmId != ''
                && vendInvoiceInfoLine.PurchLineRecId != 0
            {
                purchLineSet.add(purchLine.RecId);
            }
        }

    }

    purchPOCont = purchPOSet.pack();
    purchLineCont = purchLineSet.pack();

    return [invcAccount, currencyCode, purchPOCont, purchLineCont];
}

private static Query buildQueryForPO(PurchIdRange _purchIdRangeValue, PurchUpdate _specQty)
{
    Query query = new Query();
    QueryBuildDataSource qbdsPurchTable = query.addDataSource(tableNum(PurchTable));

    //if (_purchIdRangeValue)
    //{
    //    QueryBuildRange purchIdCriteria = qbdsPurchTable.addRange(fieldNum(PurchTable, PurchId));
    //    purchIdCriteria.value(VendInvoiceAutomationCreateLines::getRangeExpression(_purchIdRangeValue,
    //                                                                tableStr(PurchTable),
    //                                                                tableStr(PurchTable),
    //                                                                fieldStr(PurchTable, PurchId)));
    //}

    QueryBuildDataSource qbdsPurchLine = qbdsPurchTable.addDataSource(tablenum(PurchLine));
    qbdsPurchLine.joinMode(JoinMode::InnerJoin);
    qbdsPurchLine.relations(true);

    QueryBuildRange initialPOLineStatusCriteria;
    QueryBuildRange initialPOLineStoppedCriteria;

    initialPOLineStatusCriteria = qbdsPurchLine.addRange(fieldNum(PurchLine, PurchStatus));
    initialPOLineStatusCriteria.value(enum2str(PurchStatus::Received));
    initialPOLineStatusCriteria.status(RangeStatus::Locked);

    QueryBuildDataSource vendPackingSlipTransqdbs;
    vendPackingSlipTransqdbs = qbdsPurchLine.addDataSource(tableNum(vendPackingSlipTrans));
    vendPackingSlipTransqdbs.joinMode(JoinMode::InnerJoin);
    vendPackingSlipTransqdbs.addLink(fieldNum(PurchLine, InventTransId), fieldNum(VendPackingSlipTrans, InventTransId));

    initialPOLineStoppedCriteria = qbdsPurchLine.addRange(fieldNum(PurchLine, Blocked));
    initialPOLineStoppedCriteria.value(enum2str(NoYes::No));
    initialPOLineStoppedCriteria.status(RangeStatus::Locked);

    return query;
}
